('Manœuvres',[('Charge palettisée au sol : s’assurer de l’adéquation du chariot',3),('Charge palettisée au sol : positionner le chariot et la palette sur la fourche',3),('Charge palettisée au sol : vérifier le lieu de dépose et déposer avec précision',2),('Gerbage de trois charges : s’assurer de l’adéquation du chariot',3),('Gerbage : apprécier le nombre maximal de niveaux empilables',3),('Gerbage : positionner le chariot et les charges sur la fourche',3),('Gerbage : empiler avec précision sans compromettre la stabilité',3),('Gerbage : dépiler et déposer les charges à l’endroit prévu',2),('Palettier à trois niveaux (jusqu’à 3,30 m minimum) : adéquation du chariot',3),('Palettier : localiser les emplacements et évaluer les risques selon les charges',3),('Palettier : vérifier les palettes, le conditionnement et la stabilité',3),('Palettier : positionner le chariot, prendre et déposer sans heurts',3),('Palettier : déstocker et déposer à l’endroit prévu',2),('Chargement/déchargement d’un véhicule depuis le sol : adéquation du chariot',3),('Véhicule : définir sa position et vérifier les conditions autorisant l’opération',3),('Véhicule : déposer au moins trois charges en équilibrant le chargement',3),('Véhicule : décharger et déposer à l’endroit prévu',2),('Charge longue, liquide ou déformable : adéquation du chariot',3),('Charge longue, liquide ou déformable : définir la méthode de prise et manutention',2),('Charge longue, liquide ou déformable : moyens adaptés, lieu de dépose et précision',3)]),
